"graph.layout.apply" => {
    let input = decode::<GraphViewMutationInput>(arguments)?;
    let graph = self.graph.as_ref().ok_or_else(|| HeadlessMcpCallFailure::no_document("Graph"))?;
    let loaded = self.graph_view.as_mut().ok_or_else(|| HeadlessMcpCallFailure::no_document("GraphView"))?;
    let saved = fs::read_to_string(&loaded.path)
        .map_err(|error| HeadlessMcpCallFailure::persist(&loaded.path, error))?;
    let mutation = generic_tools.graph_view_apply(&graph.document, &mut loaded.document, &permissions, input).map_err(generic_failure)?;
    if mutation.success && !mutation.diff.is_empty() {
        if let Err(error) = persist_graph_view(&graph.document, loaded) {
            loaded.document = serde_json::from_str(&saved).map_err(|reload| {
                HeadlessMcpCallFailure::new("mcp.headless_reload_failed", reload.to_string())
            })?;
            return Err(error);
        }
    }
    to_value(mutation)
}
